const deliveryTypes={WAREHOUSE:{label:'ส่งระหว่างคลัง',hint:'พักยอดเป็นระหว่างทาง รับปลายทางแล้วเพิ่มสต๊อก RCV คลังปลายทาง'},FACTORY:{label:'ส่งโรงงาน',hint:'ส่งผลิต / ฝากเก็บ สินค้ายังเป็นของบริษัท ติดตามผู้รับปลายทาง'},CUSTOMER:{label:'ส่งลูกค้า',hint:'ส่งให้ลูกค้าภายนอก ยืนยันส่งแล้วลดสต๊อก OUT'},CLINIC:{label:'ส่งคลินิก',hint:'จอง → จัดไป OUT → ส่งมอบและตัดสต๊อก · ไม่ใช้รถขนส่ง'},FULFILLMENT:{label:'ส่ง Fulfillment',hint:'สินค้ายังเป็นของบริษัท ติดตามเป็นสินค้าระหว่างทางและฝากเก็บปลายทาง ไม่ถือเป็นยอดขาย'}};
const shipEsc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const shipReferenceParts=v=>String(v??'').split(/\r?\n|;|\s+(?=\d+\s*[.)])/).map(s=>s.trim()).filter(Boolean);const shipMultiline=v=>shipEsc(v).replace(/\r\n?/g,'\n').replace(/\n/g,'<br>');const shipLines=v=>shipReferenceParts(v).map(shipEsc).join('<br>');const shipNum=v=>Number(v).toLocaleString('th-TH',{maximumFractionDigits:2});
