async function deliveryApi(path='',options={}){const r=await wmsFetch('/api/deliveries'+path,{...options,headers:{...authHeaders(),...(options.headers||{})}});const b=await r.json().catch(()=>({}));if(!r.ok||!b.success)throw Error(b.message||(r.status===404?'บริการจัดส่งยังไม่พร้อม กรุณารีสตาร์ทเซิร์ฟเวอร์':'ทำรายการไม่สำเร็จ'));return b;}
