async function loadDeliveries(){if(deliverySaving||deliveryLoading)return;deliveryLoading=true;document.getElementById('shipRefresh').disabled=true;document.getElementById('shipNew').disabled=true;try{shipMessage('กำลังโหลดข้อมูล...');const old=document.getElementById('shipWarehouse').value,isTransfer=location.pathname.endsWith('/warehouse-transfer.html');if(isTransfer)applyDeliveryCategories();const query=isTransfer?'/warehouse-workflow/bootstrap?category='+encodeURIComponent(deliveryCategory)+'&whid='+encodeURIComponent(old)+'&includeStock='+(document.getElementById('shipForm').hidden?'0':'1'):location.pathname.endsWith('/load.html')?'?lean=1':'';deliveryData=await deliveryApi(query);const select=document.getElementById('shipWarehouse');select.replaceChildren();deliveryData.warehouses.forEach(w=>select.add(new Option(w.whname+' · '+(w.whdescription||''),w.whid)));if(deliveryData.warehouses.some(w=>String(w.whid)===old))select.value=old;document.getElementById('shipNew').disabled=false;applyDeliveryCategories();renderDeliveryType();renderDeliveryOrders();renderDeliveryStock();shipMessage('');}catch(e){shipMessage(e.message,true)}finally{deliveryLoading=false;document.getElementById('shipRefresh').disabled=false;}}
async function chooseDeliveryType(type){if(!deliveryTypes[type]||deliverySaving)return;if(deliveryLines.length){const r=await Swal.fire({title:'เปลี่ยนประเภทส่ง?',text:'รายการที่ยังไม่บันทึกจะถูกล้าง',showCancelButton:true,confirmButtonText:'เปลี่ยน',cancelButtonText:'กลับ'});if(!r.isConfirmed)return;}closeDeliveryForm();deliveryType=type;renderDeliveryType();renderDeliveryOrders();}
