 if(!matches.length){box.innerHTML='<div class="text-center text-muted py-4">ไม่พบสินค้าที่ตรงกับ “'+shipEsc(raw)+'”<br><small>ลองค้นหาด้วยรหัส บาร์โค้ด หรือชื่อสินค้า</small></div>';return;}
 box.innerHTML=(matches.length>50?'<div class="small text-muted mb-2">พบ '+shipNum(matches.length)+' รายการ · แสดง 50 รายการแรก กรุณาพิมพ์เพิ่มเพื่อกรองผลลัพธ์</div>':'')+stock.map(s=>{const draft=deliveryLines.find(l=>l.productId===s.ProductId&&l.locationCode===s.LocationCode),lotTransfer=deliveryType==='WAREHOUSE'&&location.pathname.endsWith('/warehouse-transfer.html')&&deliveryCategory!=='RM',available=Math.max(0,s.AvailableQuantity-(lotTransfer?0:Number(draft?.quantity||0)));return `<div class="border rounded-3 p-3 mb-2 bg-white"><div class="d-flex justify-content-between gap-2"><div><strong>${shipEsc(s.ProductCode)}</strong><div class="small">${shipEsc(s.ProductName)}</div><div class="small text-muted">${shipEsc(s.LocationCode)} · จองใบส่งอื่น ${shipNum(s.ReservedQuantity)}</div></div><div class="text-end text-nowrap"><strong class="d-block text-primary">${shipNum(available)} ${shipEsc(s.UOM)}</strong><button type="button" class="btn btn-sm btn-outline-primary mt-2" ${available<=0?'disabled':''} onclick="addDeliveryLine(${deliveryData.stock.indexOf(s)})">${lotTransfer?(draft?'แก้จำนวน ANA/LOT':'เลือก ANA/LOT'):'เพิ่มรายการ'}</button></div></div></div>`}).join('');
